package com.britishcoach.app.data.db

import androidx.room.Entity
import androidx.room.Index
import androidx.room.PrimaryKey

/** Lesson catalogue, seeded from the built-in curriculum on every start. */
@Entity(tableName = "lessons")
data class LessonEntity(
    @PrimaryKey val id: String,
    val title: String,
    val level: Int,
    val category: String,
    val targetText: String,
    /** Cached reference audio for the first item, generated by text-to-speech. */
    val referenceAudioPath: String?,
    val phoneticGuide: String?,
    val lessonOrder: Int,
)

@Entity(tableName = "practice_attempts", indices = [Index("lessonId"), Index("timestamp")])
data class PracticeAttemptEntity(
    @PrimaryKey(autoGenerate = true) val id: Long = 0,
    val lessonId: String?,
    val timestamp: Long,
    val recognizedText: String,
    val targetText: String,
    /** Length of the recording, in milliseconds. */
    val duration: Long,
    /** The coach's spoken feedback. */
    val feedback: String,
    /** JSON of the transcript comparison and any validated assessment result. */
    val assessmentData: String?,
    /** [com.britishcoach.core.model.EvidenceLevel] name. */
    val evidence: String,
    val targetWordCount: Int,
    val matchedWordCount: Int,
    /** Comma-separated target words that were missing or recognised differently. */
    val differingWords: String,
    val recordingPath: String?,
    /** 1 = easy … 3 = hard, when the learner rated it. */
    val selfRatedDifficulty: Int? = null,
    val usedAi: Boolean = false,
)

@Entity(tableName = "mistakes", indices = [Index("nextReviewAt"), Index("masteryStatus")])
data class MistakeEntity(
    @PrimaryKey(autoGenerate = true) val id: Long = 0,
    val lessonId: String?,
    val category: String,
    /** Original target sentence (or the learner's sentence in conversation). */
    val example: String,
    val recognizedText: String,
    val correctedText: String?,
    val description: String,
    val explanation: String,
    val exercise: String,
    val attemptCount: Int,
    val createdAt: Long,
    val lastPractisedAt: Long,
    val nextReviewAt: Long,
    val reviewBox: Int,
    val masteryStatus: String,
)

@Entity(tableName = "user_progress")
data class UserProgressEntity(
    @PrimaryKey val lessonId: String,
    val completionStatus: String,
    val attempts: Int,
    val lastCompletedAt: Long?,
    val revisionDueAt: Long?,
)

/** A timed stretch of practice, used for practice minutes. */
@Entity(tableName = "practice_sessions", indices = [Index("startedAt")])
data class PracticeSessionEntity(
    @PrimaryKey(autoGenerate = true) val id: Long = 0,
    val startedAt: Long,
    val durationMs: Long,
    /** LESSON, CONVERSATION or DAILY. */
    val mode: String,
)

@Entity(tableName = "settings")
data class SettingsEntity(
    @PrimaryKey val id: Int = 0,
    val preferredVoice: String? = null,
    val speechRate: Float = 0.9f,
    val dailyGoalMinutes: Int = 20,
    val feedbackDetail: String = "STANDARD",
    /** Days to keep recordings; 0 keeps them until deleted. */
    val recordingRetention: Int = 30,
    val modelId: String? = null,
    val downloadOnWifiOnly: Boolean = true,
    val useGpu: Boolean = true,
)
